from collections import deque

def transform(grid):
    g=[row[:] for row in grid]; h=len(g); w=len(g[0])
    freq={v:sum(row.count(v) for row in g) for v in {x for row in g for x in row}}
    bg=max(freq,key=freq.get)
    # Components of every non-background color.
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            col=g[r][c]
            if col==bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==col:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((col,cells))
    # Identify the T/L-shaped color key by its connected object spanning
    # horizontal and vertical strokes; repaint the nearest separate object.
    def spans(cells):
        rr=[r for r,c in cells]; cc=[c for r,c in cells]
        return (max(rr)-min(rr)+1)+(max(cc)-min(cc)+1)
    key=max(comps,key=lambda z:spans(z[1]))
    key_color,key_cells=key
    targets=[z for z in comps if z is not key and len(z[1])>1]
    if not targets: return g
    def d(cells,other): return min(abs(r-x)+abs(c-y) for r,c in cells for x,y in other)
    target=min(targets,key=lambda z:d(key_cells,z[1]))
    for r,c in target[1]: g[r][c]=key_color
    return g

if __name__=='__main__':
    import json
    print(json.dumps(transform(json.loads(input()))))", "exit_code": 0, "error": null}

