def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find 4-connected monochrome objects; compare their exact normalized shapes.
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=g[r][c]
            if color==3 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==color:
                        seen.add((a,b)); q.append((a,b))
            minr=min(x for x,y in cells); minc=min(y for x,y in cells)
            shape=frozenset((x-minr,y-minc) for x,y in cells)
            objects.append((color,cells,shape))
    # When a shape is duplicated in different colors, recolor the anomalous object
    # to the color of its matching counterpart. Exact-shape duplicates are unique here.
    for i,(col,cells,shape) in enumerate(objects):
        matches=[o for j,o in enumerate(objects) if i!=j and o[2]==shape]
        if matches:
            other=matches[0]
            for r,c in cells: g[r][c]=other[0]
            break
    return g

